OUT = Path("/app/out")
PROGRAM = OUT / "optimize.py"
ARTIFACT_NAMES = ["optimize.py", "scenario_visible.json", "scenario_peak.json", "scenario_steady.json",
                  "scenario_burst.json", "scenario_latency.json", "perf_report.json", "bottleneck_analysis.json",
                  "recommendations.json", "data_quality.json"]
SHIPPED_PREFIXES = ("VI", "PK", "ST", "BU", "LA")

H1 = [{"name": "h1", "channel": "HX7", "rate": "30000/1001", "tc": "drop", "zone": "halvard-east", "week_start": "2026-03-06", "days": 7, "day_start": "06:00:00", "daypart_set": "standard", "tol": 2, "bph": 12, "lines": 560, "failovers": 14, "live": 7, "drift": 6, "relocks": 12, "stale": 16, "prefix": "HA", "cutoff_days": 2}]
H2 = [{"name": "h2", "channel": "HX8", "rate": "25", "tc": "nondrop", "zone": "mareth-north", "week_start": "2026-04-14", "days": 6, "day_start": "05:00:00", "daypart_set": "early", "tol": 1, "bph": 11, "lines": 480, "failovers": 16, "live": 5, "drift": 40, "relocks": 30, "stale": 18, "prefix": "HB", "cutoff_days": 1},
      {"name": "h3", "channel": "HX9", "rate": "30000/1001", "tc": "drop", "zone": "halvard-west", "week_start": "2026-03-04", "days": 7, "day_start": "06:00:00", "daypart_set": "standard", "tol": 4, "bph": 12, "lines": 500, "failovers": 10, "live": 9, "drift": 8, "relocks": 10, "stale": 12, "prefix": "HC", "cutoff_days": 3}]
