TIGHT = [{"name": "tight", "channel": "HX5", "rate": "25", "tc": "nondrop", "zone": "skarn-central", "week_start": "2026-03-16", "days": 5, "day_start": "06:00:00", "daypart_set": "standard", "tol": 2, "bph": 10, "lines": 420, "failovers": 6, "live": 3, "drift": 4, "relocks": 6, "stale": 8, "prefix": "TG", "cutoff_days": 2}]
