_LOCK = _th.RLock()
_CACHE = {}
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_SENTINEL = "\x1eRESULT\x1e"
_RUNNER = (
    "import importlib.util, json, sys, time\n"
    "spec = importlib.util.spec_from_file_location('submitted_optimize', sys.argv[1])\n"
    "mod = importlib.util.module_from_spec(spec)\n"
    "spec.loader.exec_module(mod)\n"
    "t0 = time.perf_counter_ns()\n"
    "res = mod.reconcile(sys.argv[2], sys.argv[3])\n"
    "el = time.perf_counter_ns() - t0\n"
    "sys.stdout.write('\\n' + %r + json.dumps({'elapsed_ns': el, 'result': res}, sort_keys=True) + '\\n')\n"
) % _SENTINEL


def _cached(key, fn):
    with _LOCK:
        if key not in _CACHE:
            try:
                _CACHE[key] = fn()
            except Exception:
                _CACHE[key] = None
        return _CACHE[key]


def _shipped_files():
    def load():
        raw = _js.loads(_zl.decompress(_b64.b64decode(SHIPPED_DATA_B64)).decode("utf-8"))
        return raw if isinstance(raw, dict) and len(raw) == SHIPPED_FILE_COUNT else None
    return _cached("shipped_files", load)


def _corpus(label):
    table = {"h1": (EVAL_SEED, H1, {}), "h2": (EVAL_SEED + 1, H2, {}), "month": (EVAL_SEED + 2, MONTH, {}),
             "edge": (CHALLENGE_SEED, EDGE, {"edge": True}), "tight": (CHALLENGE_SEED + 1, TIGHT, {"tight": True})}
    seed, specs, kw = table[label]
    return _cached("corpus:" + label, lambda: build_corpus(seed, specs, prior_n=900, **kw))


def _materialize(files, tag):
    root = Path(_tf.mkdtemp(prefix="pab-%s-" % tag))
    data = root / ("in_" + tag)
    data.mkdir()
    for name, text in files.items():
        (data / name).write_text(text, encoding="utf-8")
        (data / name).chmod(0o644)
    root.chmod(0o755)
    data.chmod(0o755)
    return data


def _permuted(files, seed):
    out = dict(files)
    rng = _G(seed)
    for name in sorted(out):
        if name.endswith((".log", ".jsonl", ".csv", ".tsv")):
            rows = out[name].splitlines()
            head = rows[:1] if name.endswith((".csv", ".tsv")) else []
            body = rows[len(head):]
            rng.shuffle(body)
            out[name] = "\n".join(head + body) + "\n"
    return out


def _data_dir(label):
    # the second held out directory is written with every record file in shuffled row order
    if label == "h2":
        return _cached("dir:h2", lambda: _materialize(_permuted(_corpus("h2"), EVAL_SEED ^ 0x5A5A), "h2"))
    return _cached("dir:" + label, lambda: _materialize(_corpus(label), label))


def _expected(label, wl):
    return _cached("exp:%s:%s" % (label, wl), lambda: ref_reconcile(_corpus(label), wl)[0])


def _shipped_expected():
    def build():
        files = _shipped_files()
        return ref_rollups(files) if files is not None else None
    return _cached("shipped_expected", build)


def _sandbox_cmd(cmd):
    if _os.name == "posix" and _os.geteuid() == 0:
        _grant_read()
        return _SETPRIV + cmd
    return cmd


def _grant_read():
    # The verifier runs the delivered program under a dropped uid
    # (setpriv --reuid=nobody). A real agent writes /app/out/optimize.py through an
    # editor that renames a temp file into place, so it lands at mode 0600 and the
    # unprivileged child cannot read it. The verifier is root, so make the program
    # and the directories above it readable and traversable before the drop. This
    # grants read only; the privilege drop that runs the agent code is unchanged.
    if _os.name == "posix" and _os.geteuid() == 0:
        for target in (OUT.parent, OUT, PROGRAM):
            try:
                _os.chmod(target, 0o755)
            except OSError:
                pass


def _scratch():
    d = Path(_tf.mkdtemp(prefix="pab-run-"))
    d.chmod(0o777)
    return d


def _run_cli(data_dir, wl, timeout=600):
    """(returncode, stdout bytes, scratch dir) for the delivered program, unprivileged."""
    if not PROGRAM.is_file():
        return None
    scratch = _scratch()
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8", "HOME": str(scratch)}
    try:
        proc = _sp.run(_sandbox_cmd([_sys.executable, "-I", str(PROGRAM), str(data_dir), wl]), cwd=str(scratch),
                       capture_output=True, timeout=timeout, env=env)
    except Exception:
        return None
    return proc.returncode, proc.stdout, scratch


def _run_func(data_dir, wl, timeout=600):
    if not PROGRAM.is_file():
        return None
    scratch = _scratch()
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8", "HOME": str(scratch)}
    try:
        proc = _sp.run(_sandbox_cmd([_sys.executable, "-I", "-c", _RUNNER, str(PROGRAM), str(data_dir), wl]),
                       cwd=str(scratch), capture_output=True, timeout=timeout, env=env)
    except Exception:
        return None
    if proc.returncode != 0:
        return None
    text = proc.stdout.decode("utf-8", "replace")
    if _SENTINEL not in text:
        return None
    return _js.loads(text.rsplit(_SENTINEL, 1)[1])


def _parse(stdout):
    try:
        doc = _js.loads(stdout.decode("utf-8"))
    except Exception:
        return None
    return doc if isinstance(doc, dict) else None


def _cli_doc(label, wl):
    def run():
        res = _run_cli(_data_dir(label), wl)
        if res is None or res[0] != 0:
            return None
        return _parse(res[1])
    return _cached("cli:%s:%s" % (label, wl), run)


def _artifact(name):
    path = OUT / name
    try:
        if not path.is_file() or path.is_symlink() or path.stat().st_size > 200 * 1024 * 1024:
            return None
        doc = _js.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None
    return doc if isinstance(doc, dict) else None


def _safe(fn):
    try:
        return bool(fn())
    except Exception:
        return False


def _section_equal(label, wl, keys):
    got = _cli_doc(label, wl)
    want = _expected(label, wl)
    if got is None or want is None:
        return False
    return all(got.get(k) == want[k] for k in keys)


def _snapshot(path):
    return {p.name: p.read_bytes() for p in sorted(Path(path).iterdir())}


